public sealed record PriceQuote(string Source, decimal? Price)
{
    public bool IsAvailable => Price is not null;
}

public interface IPriceAggregator
{
    Task<IReadOnlyList<PriceQuote>> GetPricesAsync(string sku, CancellationToken ct);
}

public sealed class PriceAggregator(IReadOnlyList<IPriceSource> sources, TimeSpan perSourceTimeout) : IPriceAggregator
{
    public async Task<IReadOnlyList<PriceQuote>> GetPricesAsync(string sku, CancellationToken ct)
    {
        var tasks = sources.Select(s => FetchOneAsync(s, sku, ct));
        return await Task.WhenAll(tasks).ConfigureAwait(false);
    }

    private async Task<PriceQuote> FetchOneAsync(IPriceSource source, string sku, CancellationToken ct)
    {
        using var timeoutCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
        timeoutCts.CancelAfter(perSourceTimeout);
        try
        {
            var price = await source.GetPriceAsync(sku, timeoutCts.Token).ConfigureAwait(false);
            return new PriceQuote(source.Name, price);
        }
        catch (Exception) when (!ct.IsCancellationRequested)
        {
            return new PriceQuote(source.Name, Price: null);
        }
    }
}

public interface IPriceSource
{
    string Name { get; }
    Task<decimal> GetPriceAsync(string sku, CancellationToken ct);
}
